   -- The operands a function pops, 1 or 2, or 0 for a number that is
   -- not a function, and the address of its first step.
   function seq_pops (num : std_logic_vector(7 downto 0)) return natural;

   function seq_base (num : std_logic_vector(7 downto 0)) return natural;

end package fpu_seq_pkg;

package body fpu_seq_pkg is

   function seq_pops (num : std_logic_vector(7 downto 0)) return natural is
   begin
      case num is
         when X"40" => return 1; -- SIN
         when X"41" => return 1; -- COS
         when X"42" => return 1; -- TAN
         when X"43" => return 1; -- ASIN
         when X"44" => return 1; -- ACOS
         when X"45" => return 1; -- ATAN
         when X"46" => return 2; -- ATAN2
         when X"48" => return 1; -- LN
         when X"49" => return 1; -- LOG2
         when X"4A" => return 1; -- LOG10
         when X"4C" => return 1; -- EXP
         when X"4D" => return 1; -- POW2
         when X"4E" => return 2; -- POW
         when X"4F" => return 2; -- HYPOT
         when others => return 0;
      end case;
   end function seq_pops;

   function seq_base (num : std_logic_vector(7 downto 0)) return natural is
   begin
      case num is
         when X"40" => return 0; -- SIN
         when X"41" => return 702; -- COS
         when X"42" => return 1419; -- TAN
         when X"43" => return 2170; -- ASIN
         when X"44" => return 2398; -- ACOS
         when X"45" => return 2665; -- ATAN
         when X"46" => return 2864; -- ATAN2
         when X"48" => return 3269; -- LN
         when X"49" => return 3524; -- LOG2
         when X"4A" => return 3675; -- LOG10
         when X"4C" => return 3833; -- EXP
         when X"4D" => return 4021; -- POW2
         when X"4E" => return 4211; -- POW
         when X"4F" => return 4994; -- HYPOT
         when others => return 0;
      end case;
   end function seq_base;

end package body fpu_seq_pkg;
